        if (value === null || value === undefined) window.localStorage.removeItem(STORAGE_KEY);
        else window.localStorage.setItem(STORAGE_KEY, value);
        for (const legacy of LEGACY_STORAGE_KEYS) window.localStorage.removeItem(legacy);
